// Synthetic fixtures, never customer or real financial data.
export const SAMPLE_LABEL =
  "sample data generated by scripts/gen-payouts.ts and scripts/gen-vendors.ts";
export function payoutSample(week: number) {
  let seed = 3100 + week;
  const random = () =>
    (seed = (1664525 * seed + 1013904223) >>> 0) / 4294967296;
  const payouts = ["payout_id,date,gross,fee,net,status"],
    bank = ["reference,booking_date,amount,description"];
  for (let i = 0; i < 25; i++) {
    const day = 1 + ((week * 7 + i) % 28);
    const date = `2026-10-${String(day).padStart(2, "0")}`;
    const gross =
      i % 9 === 0
        ? -Math.round(random() * 10000) / 100
        : Math.round((100 + random() * 1000) * 100) / 100;
    const fee = gross < 0 ? 0 : Math.round(gross * 0.029 * 100) / 100;
    const net = Math.round((gross - fee) * 100) / 100;
    const id = `po_${week}_${i}`;
    payouts.push(
      `${id},${date},${gross.toFixed(2)},${fee.toFixed(2)},${net.toFixed(2)},${gross < 0 ? "refund" : "paid"}`,
    );
    const amount =
      net < 0 ? `($${Math.abs(net).toFixed(2)})` : `$${net.toFixed(2)}`;
    bank.push(
      `${id},${String(day).padStart(2, "0")}/10/2026,${amount},Stripe ${gross < 0 ? "refund" : "payout"}`,
    );
  }
  return { payouts: payouts.join("\n") + "\n", bank: bank.join("\n") + "\n" };
}
export function vendorSample(week: number) {
  const lines = [" SKU ,Vendor,Price,Unit"];
  for (let i = 0; i < 25; i++) {
    const row = ` sku-${i} ,  Vendor   ${i % 4}  ,"$${(1000 + week * 10 + i + 0.25).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}",${i % 2 ? "EA" : "each"}`;
    lines.push(row);
    if (i % 7 === 0) lines.push(row);
  }
  return lines.join("\n") + "\n";
}

// Enhanced fixture: transaction batches, three-day bank delay, refunds and integer-cent fees.
export function batchedPayoutSample(week: number) {
  if (!Number.isInteger(week) || week < 1 || week > 20)
    throw Error("Sample week must be 1–20");
  let seed = 9100 + week;
  const random = () =>
    (seed = (1664525 * seed + 1013904223) >>> 0) / 4294967296;
  const csv = (rows: (string | number)[][]) =>
    rows
      .map((r) =>
        r
          .map((v) => {
            const s = String(v);
            return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
          })
          .join(","),
      )
      .join("\n") + "\n";
  const iso = (d: Date) => d.toISOString().slice(0, 10),
    day = (n: number) => new Date(Date.UTC(2026, 0, 5 + (week - 1) * 7 + n));
  const payouts: (string | number)[][] = [
    [
      "transaction_id",
      "settlement_id",
      "expected_date",
      "gross_cents",
      "fee_cents",
      "net_cents",
      "status",
    ],
  ];
  const groups = new Map<
    string,
    { net: number; count: number; date: string; delay: number }
  >();
  for (let i = 0; i < 25; i++) {
    const refund = i % 9 === 0,
      gross = (refund ? -1 : 1) * (1000 + Math.floor(random() * 99000));
    const fee = refund ? 0 : Math.floor((gross * 29 + 500) / 1000),
      net = gross - fee;
    const group = refund
      ? `refund_${week}_${i}`
      : `batch_${week}_${Math.floor(i / 5)}`;
    const offset = Math.floor(i / 5),
      date = iso(day(offset)),
      delay = 1 + ((week + offset) % 3);
    payouts.push([
      `tx_${week}_${i}`,
      group,
      date,
      gross,
      fee,
      net,
      refund ? "refund" : "paid",
    ]);
    const previous = groups.get(group);
    if (previous) {
      previous.net += net;
      previous.count++;
    } else groups.set(group, { net, count: 1, date, delay });
  }
  const bank: (string | number)[][] = [
    [
      "reference",
      "booking_date",
      "amount_minor",
      "currency",
      "display_amount",
      "description",
    ],
  ];
  const expectedRows = [];
  for (const [id, g] of groups) {
    const booked = new Date(g.date + "T00:00:00Z");
    booked.setUTCDate(booked.getUTCDate() + g.delay);
    const date = `${String(booked.getUTCDate()).padStart(2, "0")}/${String(booked.getUTCMonth() + 1).padStart(2, "0")}/${booked.getUTCFullYear()}`;
    const grouped = Math.abs(g.net).toLocaleString("en-US"),
      minor = g.net < 0 ? `(${grouped})` : grouped,
      display = (Math.abs(g.net) / 100).toFixed(2);
    bank.push([
      id,
      date,
      minor,
      "USD",
      g.net < 0 ? `($${display})` : `$${display}`,
      `Synthetic settlement of ${g.count} transactions`,
    ]);
    expectedRows.push({
      settlement_id: id,
      net_cents: g.net,
      amount_minor: g.net,
      transaction_count: g.count,
      delta_cents: 0,
    });
  }
  // Reverse bank row order to make accidental positional matching fail.
  return {
    payouts: csv(payouts),
    bank: csv([bank[0]!, ...bank.slice(1).reverse()]),
    expected: {
      columns: [
        "settlement_id",
        "net_cents",
        "amount_minor",
        "transaction_count",
        "delta_cents",
      ],
      rows: expectedRows,
    },
  };
}

// Vendor price-list cleanup fixture: messy headers, spacing, casing, currency
// strings, unit synonyms and exact duplicate rows. Reference rows are computed
// from the generator's own ledger, independently of any pipeline.
const VENDORS = [
  "Acme Supplies",
  "Northwind Traders",
  "Globex Foods",
  "Initech Parts",
];
const UNITS: [string, string][] = [
  ["EA", "each"],
  ["each", "each"],
  ["Each", "each"],
  ["pcs", "each"],
  ["BX", "box"],
  ["box", "box"],
  ["CS", "case"],
];
export function vendorCleanupSample(week: number) {
  if (!Number.isInteger(week) || week < 1 || week > 20)
    throw Error("Sample week must be 1–20");
  let seed = 7300 + week;
  const random = () =>
    (seed = (1664525 * seed + 1013904223) >>> 0) / 4294967296;
  const quote = (v: string) =>
    /[",\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v;
  const lines = [" SKU ,Vendor Name,Unit Price,UOM"];
  const expected: {
    sku: string;
    vendor: string;
    price: number;
    unit: string;
  }[] = [];
  for (let i = 0; i < 30; i++) {
    const sku = `SKU-${String(100 + i)}`;
    const vendor = VENDORS[i % VENDORS.length]!;
    const cents = 500 + Math.floor(random() * 250000);
    const [rawUnit, unit] = UNITS[Math.floor(random() * UNITS.length)]!;
    const messySku = `${i % 3 ? " " : ""}${i % 2 ? sku.toLowerCase() : sku} `;
    const messyVendor = `${i % 4 === 0 ? "  " : ""}${
      i % 3 === 0 ? vendor.toUpperCase() : vendor.replace(" ", "   ")
    }${i % 5 === 0 ? " " : ""}`;
    const price = `$${(cents / 100).toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}`;
    const row = [messySku, messyVendor, price, rawUnit].map(quote).join(",");
    lines.push(row);
    if (i % 6 === 0) lines.push(row);
    expected.push({
      sku,
      vendor: vendor.toLowerCase(),
      price: cents / 100,
      unit,
    });
  }
  return {
    csv: lines.join("\n") + "\n",
    expected: { columns: ["sku", "vendor", "price", "unit"], rows: expected },
  };
}
